<?php require_once __DIR__ . '/functions.php'; $search=trim($_GET['q']??''); $active=$_GET['category']??''; $items=products($search,$active); $categories=db()->query('SELECT * FROM categories ORDER BY id')->fetchAll(); ?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="نُقطة — متجر مصغر للأشياء التي تجعل يومك ألطف."><title>نُقطة | متجر مصغر</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="topbar">شحن مجاني للطلبات فوق ١٥٠ ر.س · منتجات مختارة بعناية</div><header class="container nav"><a class="logo" href="index.php">نُقطة <span>•</span></a><nav class="navlinks"><a href="#products">المنتجات</a><a href="#story">عن نُقطة</a><a href="admin-login.php">الإدارة</a></nav><a class="cart" href="cart.php">السلة (<?=cartCount()?>)</a></header><main><section class="container hero"><div><span class="eyebrow">أشياء صغيرة، أثر كبير</span><h1>اختيارات لطيفة<br>لـ <em>يومك العادي.</em></h1><p>نُقطة متجر مصغر نؤمن أن التفاصيل البسيطة تصنع فرقًا كبيرًا. اكتشف أشياء عملية، جميلة، ومختارة بذوق.</p><a class="btn" href="#products">تصفح المجموعة ↓</a></div><div class="hero-art"><span class="hero-emoji">🛍️</span></div></section><section class="container products" id="products"><div class="section-head"><div><h2>المجموعة الحالية</h2><p>منتجات نحب وجودها في كل بيت.</p></div></div><form class="filters" method="get"><input name="q" value="<?=e($search)?>" placeholder="ابحث عن منتج..." style="border:1px solid var(--line);border-radius:99px;padding:9px 15px;font:inherit;background:var(--card);min-width:220px"><button class="filter active">بحث</button><?php foreach($categories as $cat):?><a class="filter <?=((string)$active===(string)$cat['id'])?'active':''?>" href="?category=<?=$cat['id']?>#products"><?=e($cat['name'])?></a><?php endforeach; if($search||$active):?><a class="filter" href="index.php#products">إظهار الكل</a><?php endif;?></form><div class="grid"><?php if(!$items):?><div class="empty" style="grid-column:1/-1">لا توجد منتجات مطابقة لبحثك.</div><?php endif; foreach($items as $p):?><article class="product"><a href="product.php?id=<?=$p['id']?>"><div class="product-visual" style="background:<?=e($p['accent'])?>"><span class="badge"><?=e($p['badge'])?></span><span class="product-emoji"><?=e($p['emoji'])?></span></div></a><div class="product-body"><h3><a href="product.php?id=<?=$p['id']?>"><?=e($p['name'])?></a></h3><p><?=e($p['description'])?></p><div class="price"><?=money((int)$p['price'])?><?php if($p['compare_at_price']):?><span class="old"><?=money((int)$p['compare_at_price'])?></span><?php endif;?></div><form method="post" action="cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="btn add">أضف إلى السلة</button></form></div></article><?php endforeach;?></div></section><section class="container" id="story"><div class="notice"><h2>نختارها كأننا نشتري لأنفسنا</h2><p>جودة واضحة، سعر عادل، وتجربة شراء بلا تعقيد.</p></div></section></main><footer><div class="container">© <?=date('Y')?> نُقطة · تفاصيل صغيرة ليوم أجمل.</div></footer></body></html>
